import json, re, decimal
from pathlib import Path
p=Path('/root/infusion_batch_analysis.json')
data=json.loads(p.read_text())
errors=[]
expected_assumptions={
 '7_day_model': {'days_per_delivery': 7, 'deliveries_per_year': 52},
 '14_day_model': {'days_per_delivery': 14, 'deliveries_per_year': 26},
 'annual_supply_cost_formula': 'bag_supply_cost_usd * active_patients * deliveries_per_year',
 'decision_threshold_usd': 15000,
}
if data.get('assumptions') != expected_assumptions:
    errors.append('assumptions mismatch')
codes=[t['therapy_code'] for t in data['therapies']]
if codes != sorted(codes):
    errors.append('therapy codes not sorted')
valid_decisions={'move_to_14_day','keep_7_day'}
if data.get('recommendation',{}).get('decision') not in valid_decisions:
    errors.append('invalid decision')
# Check JSON numeric currency fields have at most 2 decimal places by inspecting Decimal from serialized JSON.
raw=p.read_text()
parsed=json.loads(raw, parse_float=decimal.Decimal, parse_int=decimal.Decimal)
currency_key_fragments=('cost','revenue','margin','payment','difference','threshold')
def walk(obj,path=''):
    if isinstance(obj, dict):
        for k,v in obj.items():
            yield from walk(v, f'{path}.{k}' if path else k)
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            yield from walk(v, f'{path}[{i}]')
    else:
        yield path,obj
for path,val in walk(parsed):
    key=path.split('.')[-1]
    if any(frag in key for frag in currency_key_fragments) and isinstance(val, decimal.Decimal):
        exponent=-val.as_tuple().exponent
        if exponent > 2:
            errors.append(f'{path} has >2 decimals: {val}')
summary=Path('/root/infusion_batch_summary.md').read_text()
non_empty=[line for line in summary.splitlines() if line.strip()]
if not (4 <= len(non_empty) <= 8):
    errors.append(f'summary has {len(non_empty)} non-empty lines')
for needed in ('Total 7-day annual margin:', 'Total 14-day annual margin:', 'Absolute margin difference:', f"Recommendation: {data['recommendation']['decision']}"):
    if needed not in summary:
        errors.append(f'summary missing {needed}')
print('VALIDATION OK' if not errors else 'VALIDATION ERRORS:\n'+'\n'.join(errors))
print('therapy_codes=', codes)
print('non_empty_summary_lines=', len(non_empty))
